package com.insurance.claims.repository;

import com.insurance.claims.entity.InsuranceClaim;
import org.springframework.data.repository.CrudRepository;
import org.springframework.data.rest.core.annotation.RepositoryRestResource;
import org.springframework.data.rest.core.annotation.RestResource;
import org.springframework.security.access.prepost.PreAuthorize;
import java.util.UUID;

@RepositoryRestResource(collectionResourceRel = "claims", path = "claims")
public interface InsuranceClaimRepository extends CrudRepository<InsuranceClaim, UUID> {

    @Override
    @PreAuthorize("hasRole('CLAIMS_ADJUSTER') or (hasRole('POLICYHOLDER') and #entity.policyNumber == principal.policyNumber)")
    <S extends InsuranceClaim> S save(S entity);

    @Override
    @RestResource(exported = false)
    void deleteById(UUID id);
}
